  "hypothesis": "Replacing the shuffled cut scan with a coarse-to-fine search around the strongest cuts will find a better packet-order change and target a verified gain of at least 1e-5 after weight repair.",
  "rationale": "The previous search spends its topology budget on isolated cuts, even though useful packet boundaries may lie between them. Adaptive refinement preserves the same rotation/reflection and weight-repair method while concentrating evaluations near promising cuts rather than polishing the incumbent structure.",
  "source": "import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'cuts': (36, 12, 120),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    coarse_end = start + 0.56 * float(params['search_fraction']) * budget_s
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline - 2.0:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf
    tested = {}
    leaders = [[], [], []]

    def approximate(f):
        s = fft.rfft(f, m, workers=1)
        c = fft.irfft(s*s, m, workers=1)[:2*n-1]
        return float((2*np.dot(c, c) + np.dot(c[:-1], c[1:])) /
                     (3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        k = int(k)
        if not 0 < k < n or time.monotonic() >= search_end:
            return None
        key = (k, mode)
        if key in tested:
            return tested[key]
        f = make(k, mode)
        score = approximate(f)
        tested[key] = score
        leaders[mode].append((score, k))
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline - 2.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        return score

    cuts = set()
    count = int(params['cuts'])
    cumulative = np.cumsum(f0)
    for q in np.linspace(0.01, 0.99, count):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(np.searchsorted(cumulative, q*cumulative[-1])))
    for d in np.geomspace(1, max(2, n//3), 18):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(d))
        cuts.add(n-int(d))
    occupied = f0 > 0
    changes = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, changes, n]
    widths = np.diff(edges)
    order = np.argsort(widths)[::-1][:24]
    for j in order:
        if time.monotonic() >= coarse_end:
            break
        if not occupied[edges[j]]:
            cuts.add(int((edges[j]+edges[j+1])//2))
            cuts.add(int(edges[j]))
            cuts.add(int(edges[j+1]))
    cuts = sorted(k for k in cuts if 0 < k < n)
    rng.shuffle(cuts)
    # Each coarse cut is tested in all three modes before the next cut.
    for k in cuts:
        if time.monotonic() >= coarse_end:
            break
        modes = rng.permutation(3)
        for mode in modes:
            if time.monotonic() >= coarse_end:
                break
            inspect(k, int(mode))

    # Refine several basins per mode, retaining improvements at each scale.
    basins = []
    for mode in range(3):
        if time.monotonic() >= search_end:
            break
        ranked = sorted(leaders[mode], reverse=True)
        chosen = []
        for score, k in ranked:
            if time.monotonic() >= search_end:
                break
            if all(abs(k-j) > max(2, n//128) for j in chosen):
                chosen.append(k)
                basins.append([score, k, mode, max(1, n//64)])
            if len(chosen) == 2:
                break
    while basins and time.monotonic() < search_end:
        next_basins = []
        for score, k, mode, step in sorted(basins, reverse=True):
            if time.monotonic() >= search_end:
                break
            local_score, local_k = score, k
            # Snap each proposed cut to the nearest support edge as well.
            for direction in (-1, 1):
                if time.monotonic() >= search_end:
                    break
                target = min(n-1, max(1, k + direction*step))
                proposals = [target]
                if len(changes):
                    pos = int(np.searchsorted(changes, target))
                    near = changes[max(0, pos-1):min(len(changes), pos+1)]
                    if len(near):
                        proposals.append(int(near[np.argmin(abs(near-target))]))
                for trial in proposals:
                    if time.monotonic() >= search_end:
                        break
                    value = inspect(trial, mode)
                    if value is not None and value > local_score:
                        local_score, local_k = value, trial
            if step > 1:
                next_basins.append([local_score, local_k, mode, max(1, step//2)])
        basins = next_basins

    if contender is None or contender_score < baseline - float(params['repair_tolerance']):
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
    if time.monotonic() >= deadline - 2.0:
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    base = contender
    spec = fft.rfft(base, m, workers=1)
    peak = fft.irfft(spec*spec, m, workers=1)[:2*n-1].max()
    base = base / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]
    beta = float(params['beta'])

    class Stop(Exception):
        pass

    def objective(x):
        nonlocal best_score, best_f
        if time.monotonic() >= deadline - 2.0:
            raise Stop()
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        sp = fft.rfft(f, m, workers=1)
        c = fft.irfft(sp*sp, m, workers=1)[:2*n-1]
        peak = c.max()
        e = np.exp(beta*(c-peak))
        z = e.sum()
        smooth = peak + np.log(z)/beta
        num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
        total = f.sum()
        quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
        if quick > best_score + 1e-13 and time.monotonic() < deadline - 1.6:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        if time.monotonic() >= deadline - 1.3:
            raise Stop()
        g = 4*c
        g[1:] += c[:-1]
        g[:-1] += c[1:]
        g /= 3*num
        g -= e/(z*smooth)
        corr = fft.irfft(fft.rfft(g,m,workers=1)*np.conj(sp),m,workers=1)[:n]
        local = (2*corr[indices]-2/total)*active
        grad = 2*x*np.bincount(labels,weights=local,minlength=groups)
        value = np.log(num)-2*np.log(total)-np.log(smooth)
        return -value, -grad

    try:
        minimize(objective, np.ones(groups), jac=True, method='L-BFGS-B',
                 options={'maxcor': 7, 'maxiter': 10000, 'maxfun': 20000,
                          'ftol': 0.0, 'gtol': 0.0, 'maxls': 15})
    except Stop:
        pass
    return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
"
}
